// Custom MIDI Editor — logic (Rune). Editor::new declares params and
// triggers; the UI reaches them by id (ui.knob('velocity'), logic.trigger('I')).

pub fn describe() {
  Editor::new("Chord Pad")
    .knob("velocity", 1.0, 127.0, 96.0)
    .trigger("I").trigger("IV").trigger("V").trigger("vi")
}

pub fn new() { #{ velocity: 96.0 } }

pub fn param(state, id, value) {
  if id == "velocity" { state.velocity = value; }
}

// Triggers return the notes to write into the clip (pitch, velocity, beats).
pub fn trigger(state, id, args) {
  let root = match id { "I" => 60, "IV" => 65, "V" => 67, "vi" => 69, _ => 60 };
  let third = if id == "vi" { 3 } else { 4 };
  let beat = args.beat;
  [
    MidiEvent::note(root, state.velocity, 1.0).at(beat),
    MidiEvent::note(root + third, state.velocity, 1.0).at(beat),
    MidiEvent::note(root + 7, state.velocity, 1.0).at(beat),
  ]
}

files.ui:
// Custom MIDI Editor — UI. ui.button(id) fires a logic trigger,
// ui.knob(id) binds a logic param; root / h for anything custom.
// Top-level code is the render body: it re-runs on every MIDI update.

// notes beats are absolute; logic MidiEvents are relative to the section.
const nextBeat = notes.length
  ? Math.max(...notes.map((n) => n.beat + n.duration)) - sectionStartBeat
  : 0;
const pad = (id) => ui.button(id, { args: { beat: nextBeat } });
root.append(
  h('div', { class: 'row' }, pad('I'), pad('IV'), pad('V'), pad('vi'), ui.knob('velocity')),
  h('div', { class: 'hint' }, notes.length + ' notes · next chord at beat ' + nextBeat),
);

